// The site's worker: OpenNext's generated worker for every request, plus a daily
// cron (see "triggers" in wrangler.jsonc) that sends the monthly reminder emails.
// @ts-ignore .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; SITE_ORIGIN?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

const worker = {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) return;
    const origin = env.SITE_ORIGIN || "https://offset-website.itsian123.workers.dev";
    const req = new Request(`${origin}/api/reminders/run`, { method: "POST", headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    const res: Response = await handler.fetch(req, env, ctx);
    console.log("reminders:", res.status, await res.text());
  },
};

export default worker;
